window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-31e6be861e9845bb"]={"versions": [{"id": "FIG-31e6be861e9845bb", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR-ECU-Konfigurationsparameterdefinition (ECUC Parameter Configuration) für das BSW-Modul Dem (Diagnostic Event Manager) im Bereich System Services. Es definiert die metamodellbasierte Struktur zur Konfiguration des Features DemMultiEventTriggering.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert vier Entitäten und deren Beziehungen:</p>\n<ul class=\"fig-list\"><li>Container <code>DemMultiEventTriggering</code> (Typ: <code>EcucParamConfContainerDef</code>, Multiplizität 0..65535).\n</li><li>Referenzdefinition <code>DemMultiEventTriggeringSlaveEventRef</code> (Typ: <code>EcucReferenceDef</code>, Multiplizität 1..255).\n</li><li>Referenzdefinition <code>DemMultiEventTriggeringMasterEventRef</code> (Typ: <code>EcucReferenceDef</code>, Multiplizität 1..1).\n</li><li>Zielcontainer <code>DemEventParameter</code> (Typ: <code>EcucParamConfContainerDef</code>, Multiplizität 1..65535).\n</li></ul>\n<p class=\"fig-p\">Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>DemMultiEventTriggering</code> aggregiert per Komposition (<code>+reference</code>) 1 bis 255 Instanzen von <code>DemMultiEventTriggeringSlaveEventRef</code>.\n</li><li><code>DemMultiEventTriggering</code> aggregiert per Komposition (<code>+reference</code>) genau 1 Instanz von <code>DemMultiEventTriggeringMasterEventRef</code>.\n</li><li><code>DemMultiEventTriggeringSlaveEventRef</code> referenziert über eine gerichtete Assoziation (<code>+destination</code>) eine Instanz von <code>DemEventParameter</code>.\n</li><li><code>DemMultiEventTriggeringMasterEventRef</code> referenziert über eine gerichtete Assoziation (<code>+destination</code>) eine Instanz von <code>DemEventParameter</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmetamodell ohne dynamische Laufzeitsequenz. Zur Konfigurations- bzw. Generierungszeit verknüpft jede <code>DemMultiEventTriggering</code>-Instanz genau ein Master-Event (<code>DemMultiEventTriggeringMasterEventRef</code>) mit mindestens einem und bis zu 255 Slave-Events (<code>DemMultiEventTriggeringSlaveEventRef</code>). Laufzeitverhalten im Dem leitet Statusänderungen oder Trigger des Master-Events an die referenzierten Slave-Events weiter.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Konfigurationsstruktur für den Dem-ECUC-Parameterbaum:</p>\n<ul class=\"fig-list\"><li>Ein Dem-Modul kann 0 bis 65535 Multi-Event-Triggering-Gruppen definieren.\n</li><li>Jede Gruppe muss zwingend genau eine Master-Event-Referenz (<code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>) enthalten.\n</li><li>Jede Gruppe muss mindestens 1 und darf maximal 255 Slave-Event-Referenzen (<code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 255</code>) umfassen.\n</li><li>Sowohl Master als auch Slaves müssen auf gültige <code>DemEventParameter</code>-Containerinstanzen im Dem verweisen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-a7c8a5189663d3c4", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR-ECU-Konfigurationsparameterdefinition (ECUC Parameter Configuration) für das BSW-Modul Dem (Diagnostic Event Manager) im Bereich System Services. Es definiert die metamodellbasierte Struktur zur Konfiguration des Features DemMultiEventTriggering.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert vier Entitäten und deren Beziehungen:</p>\n<ul class=\"fig-list\"><li>Container <code>DemMultiEventTriggering</code> (Typ: <code>EcucParamConfContainerDef</code>, Multiplizität 0..65535).\n</li><li>Referenzdefinition <code>DemMultiEventTriggeringSlaveEventRef</code> (Typ: <code>EcucReferenceDef</code>, Multiplizität 1..255).\n</li><li>Referenzdefinition <code>DemMultiEventTriggeringMasterEventRef</code> (Typ: <code>EcucReferenceDef</code>, Multiplizität 1..1).\n</li><li>Zielcontainer <code>DemEventParameter</code> (Typ: <code>EcucParamConfContainerDef</code>, Multiplizität 1..65535).\n</li></ul>\n<p class=\"fig-p\">Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>DemMultiEventTriggering</code> aggregiert per Komposition (<code>+reference</code>) 1 bis 255 Instanzen von <code>DemMultiEventTriggeringSlaveEventRef</code>.\n</li><li><code>DemMultiEventTriggering</code> aggregiert per Komposition (<code>+reference</code>) genau 1 Instanz von <code>DemMultiEventTriggeringMasterEventRef</code>.\n</li><li><code>DemMultiEventTriggeringSlaveEventRef</code> referenziert über eine gerichtete Assoziation (<code>+destination</code>) eine Instanz von <code>DemEventParameter</code>.\n</li><li><code>DemMultiEventTriggeringMasterEventRef</code> referenziert über eine gerichtete Assoziation (<code>+destination</code>) eine Instanz von <code>DemEventParameter</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmetamodell ohne dynamische Laufzeitsequenz. Zur Konfigurations- bzw. Generierungszeit verknüpft jede <code>DemMultiEventTriggering</code>-Instanz genau ein Master-Event (<code>DemMultiEventTriggeringMasterEventRef</code>) mit mindestens einem und bis zu 255 Slave-Events (<code>DemMultiEventTriggeringSlaveEventRef</code>). Laufzeitverhalten im Dem leitet Statusänderungen oder Trigger des Master-Events an die referenzierten Slave-Events weiter.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Konfigurationsstruktur für den Dem-ECUC-Parameterbaum:</p>\n<ul class=\"fig-list\"><li>Ein Dem-Modul kann 0 bis 65535 Multi-Event-Triggering-Gruppen definieren.\n</li><li>Jede Gruppe muss zwingend genau eine Master-Event-Referenz (<code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>) enthalten.\n</li><li>Jede Gruppe muss mindestens 1 und darf maximal 255 Slave-Event-Referenzen (<code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 255</code>) umfassen.\n</li><li>Sowohl Master als auch Slaves müssen auf gültige <code>DemEventParameter</code>-Containerinstanzen im Dem verweisen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-31e6be861e9845bb", "to": "FIG-a7c8a5189663d3c4", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><code>DemMultiEventTriggering</code>: Leerzeichen vor dem Doppelpunkt im Klassennamen entfernt (<code>DemMultiEventTriggering :</code> zu <code>DemMultiEventTriggering:</code>).\n</li><li><code>DemMultiEventTriggeringSlaveEventRef</code>: Leerzeichen vor dem Doppelpunkt im Klassennamen entfernt (<code>DemMultiEventTriggeringSlaveEventRef :</code> zu <code>DemMultiEventTriggeringSlaveEventRef:</code>).\n</li><li><code>DemMultiEventTriggeringMasterEventRef</code>: Leerzeichen vor dem Doppelpunkt im Klassennamen entfernt (<code>DemMultiEventTriggeringMasterEventRef :</code> zu <code>DemMultiEventTriggeringMasterEventRef:</code>).\n</li><li><code>DemEventParameter</code>: Leerzeichen vor dem Doppelpunkt im Klassennamen entfernt (<code>DemEventParameter :</code> zu <code>DemEventParameter:</code>).\n</li></ul>"}]};
